-- 0003: TOTP MFA and recovery codes (ADR-005, P0-009).
-- TOTP secrets are stored only AES-256-GCM encrypted with MFA_ENCRYPTION_KEY (kept outside the
-- database). Recovery codes are stored only as SHA-256 hashes.

ALTER TABLE users
  ADD COLUMN totp_secret_enc bytea,
  -- Last accepted TOTP time step; codes for this step or earlier are replays.
  ADD COLUMN totp_last_step bigint,
  ADD CONSTRAINT users_mfa_requires_secret CHECK (NOT mfa_enabled OR totp_secret_enc IS NOT NULL);

ALTER TABLE login_challenges
  -- Secret generated by mfa/setup, promoted to users only after a correct first code.
  ADD COLUMN pending_totp_secret_enc bytea,
  ADD COLUMN failed_attempts integer NOT NULL DEFAULT 0 CHECK (failed_attempts >= 0);

CREATE TABLE recovery_codes (
  id         uuid PRIMARY KEY DEFAULT uuidv7(),
  user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  code_hash  bytea NOT NULL CHECK (octet_length(code_hash) = 32),
  used_at    timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT recovery_codes_user_code_unique UNIQUE (user_id, code_hash)
);

CREATE INDEX recovery_codes_user_unused_idx ON recovery_codes (user_id) WHERE used_at IS NULL;

GRANT SELECT, INSERT, UPDATE, DELETE ON recovery_codes TO nalara_app;
